  const dynamicConfig = useMemo<IoAssistDynamicConfig>(
    () => ({
      user: {
        id: "acme-advisor",
        name: "ACME Advisor",
      },
    }),
    [],
  );

  return (
    <main className="assist-shell">
      <IoAssist staticConfig={staticConfig} dynamicConfig={dynamicConfig} />
    </main>
  );
}

export default App;

import { useMemo } from "react";
import IOBrowser from "@interopio/browser";
import {
  IoAssist,
  type IoAssistDynamicConfig,
  type IoAssistStaticConfig,
} from "@interopio/io-assist-react";
import IOWorkspaces from "@interopio/workspaces-api";
import "./App.css";

// this must be defined;
const AGENT_SERVER_URL = "http://localhost:4111";

const createIOConnect: typeof IOBrowser = async (config) => {
  const io = await IOBrowser(config);

  (window as any).io = io;

  return io;
};

const staticConfig: IoAssistStaticConfig = {
  connectConfig: {
    browser: {
      factory: createIOConnect,
      config: {
        libraries: [IOWorkspaces],
        modals: {
          dialogs: {
            enabled: true,
          },
        },
      },
    },
  },
  defaultAgentName: "io-agent",
  aiWebConfig: {
    agentServer: {
      baseUrl: AGENT_SERVER_URL,
    },
    codeMode: {
      factory: IoCodeModeFactory,
      config: {
        wasmLocation: "/quickjs/emscripten-module.wasm",
        // The timeout keeps running while the user decides, so allow time for approval.
        timeout: 120_000,
        interceptors: {
          // Ask the user before any payment is submitted. Denying returns a policy error
          // to the model, and the tool never runs.
          onToolCall: async ({ tool, input }) => {
            if (tool.name !== "submit_payment") {
              return { allowed: true };
            }
            const approved = window.confirm(
              `Approve this payment?\n\n${JSON.stringify(input, null, 2)}`,
            );
            return approved
              ? { allowed: true }
              : { allowed: false, reason: "The user declined the payment." };
          },
        },
      },
    },
    mcp: {
      clientsConfig: {
        capabilities: {},
      },
      remoteServers: [
        {
          streamableHttp: {
            name: "acme-mcp",
            url: "http://localhost:7070/mcp",
          },
        },
      ],
    },
  },
};

function App() {
  const dynamicConfig = useMemo<IoAssistDynamicConfig>(
    () => ({
      user: {
        id: "acme-advisor",
        name: "ACME Advisor",
      },
    }),
    [],
  );

  return (
    <main className="assist-shell">
      <IoAssist staticConfig={staticConfig} dynamicConfig={dynamicConfig} />
    </main>
  );
}

export default App;
